tool_schemas.implementation:
def tavily_search(api_key_id=None, query=None, search_depth=None, max_results=None, include_domains=None, exclude_domains=None, include_answer=None, include_raw_content=None, include_images=None, raw_input=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64, secrets
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0242000" if __import__("os").path.isdir("./environment_mix/0242000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")
    day_key = now.strftime("%Y-%m-%d")

    # --- helpers ---
    CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(prefix):
        # not a true ULID, but stable and matches regex: prefix + '_' + crockford base32 length>=10
        rand = "".join(secrets.choice(CROCKFORD) for _ in range(16))
        return f"{prefix}_{rand}"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _token_estimate(text):
        if not text:
            return 0
        # rough: 4 chars per token
        return max(1, len(text) // 4)

    def _domain_from_url(u):
        try:
            p = urlparse(u)
            return (p.hostname or "").lower()
        except Exception:
            return ""

    def _log_call(api_key_row, endpoint, status, latency_ms, request_id=None, tokens=0, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rec = {
            "request_log_id": _ulid_like("reqlog"),
            "endpoint": endpoint,
            "api_key_id": api_key_row["api_key_id"] if api_key_row else None,
            "api_key_prefix": api_key_row.get("key_prefix") if api_key_row else None,
            "request_id": request_id,
            "status": status,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "timestamp": now_iso,
            "latency_ms": int(latency_ms),
            "utc_day": day_key,
            "tokens": int(tokens) if isinstance(tokens, int) else 0
        }
        logs.append(rec)
        _save("request_logs.json", logs)

    def _get_usage(api_key_id):
        usage = _load("api_key_usage.json")
        if not isinstance(usage, list):
            usage = []
        row = None
        for r in usage:
            if r.get("api_key_id") == api_key_id and r.get("utc_day") == day_key:
                row = r
                break
        if row is None:
            row = {"api_key_id": api_key_id, "utc_day": day_key, "completed_requests": 0, "completed_tokens": 0, "updated_at": now_iso}
            usage.append(row)
            _save("api_key_usage.json", usage)
        return usage, row

    def _count_completed_from_store(api_key_id):
        # completed = terminal statuses for both search and extract
        sr = _load("search_requests.json")
        er = _load("extract_requests.json")
        if not isinstance(sr, list): sr = []
        if not isinstance(er, list): er = []
        terminals = {"succeeded", "failed", "cancelled"}
        c = 0
        for r in sr:
            if r.get("api_key_id") == api_key_id and r.get("status") in terminals:
                dt = _parse_dt(r.get("finished_at")) or _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at"))
                if dt and dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%d") == day_key:
                    c += 1
        for r in er:
            if r.get("api_key_id") == api_key_id and r.get("status") in terminals:
                dt = _parse_dt(r.get("finished_at")) or _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at"))
                if dt and dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%d") == day_key:
                    c += 1
        return c

    def _effective_api_key_row(api_key_id_param):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        # If api_key_id provided, must match exactly.
        if api_key_id_param is not None:
            if not isinstance(api_key_id_param, str):
                return None, _err("VALIDATION_ERROR", "api_key_id must be a string")
            if not re.match(r"^tav_key_[0-9A-HJKMNP-TV-Z]{10,}$", api_key_id_param):
                return None, _err("VALIDATION_ERROR", "api_key_id has invalid format")
            for k in keys:
                if k.get("api_key_id") == api_key_id_param:
                    return k, None
            return None, _err("UNAUTHORIZED", "API key not found")
        # Ambient auth: pick an active key that can serve the call.
        for k in keys:
            if k.get("status") == "active":
                return k, None
        return None, _err("UNAUTHORIZED", "No active API key available")

    def _enforce_quota(api_key_row):
        if api_key_row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active")
        q = api_key_row.get("quota_daily_requests")
        if not isinstance(q, int) or q < 0:
            return _err("UNAUTHORIZED", "API key quota is invalid")
        # Use usage file if present; also reconcile with store to prevent bypass.
        usage_all, usage_row = _get_usage(api_key_row["api_key_id"])
        completed = usage_row.get("completed_requests")
        if not isinstance(completed, int) or completed < 0:
            completed = 0
        completed_store = _count_completed_from_store(api_key_row["api_key_id"])
        if completed_store > completed:
            usage_row["completed_requests"] = completed_store
            usage_row["updated_at"] = now_iso
            _save("api_key_usage.json", usage_all)
            completed = completed_store
        if completed >= q:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota_daily_requests=q, completed_requests=completed, utc_day=day_key)
        return None

    # --- validate inputs ---
    if query is None or not isinstance(query, str) or len(query.strip()) < 1:
        # log attempt if possible with ambient key resolution
        api_key_row, _ = _effective_api_key_row(api_key_id)
        _log_call(api_key_row, "tavily-search", "error", (time.time() - t0) * 1000, tokens=0, error={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    query = query.strip()

    if search_depth is None:
        search_depth = "basic"
    if not isinstance(search_depth, str) or search_depth not in ("basic", "advanced"):
        api_key_row, _ = _effective_api_key_row(api_key_id)
        _log_call(api_key_row, "tavily-search", "error", (time.time() - t0) * 1000, tokens=0, error={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "search_depth must be one of: basic, advanced")

    if max_results is None:
        max_results = 5
    if not isinstance(max_results, int) or max_results < 1 or max_results > 50:
        api_key_row, _ = _effective_api_key_row(api_key_id)
        _log_call(api_key_row, "tavily-search", "error", (time.time() - t0) * 1000, tokens=0, error={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "max_results must be an integer in range 1–50")

    def _validate_domains(lst, name):
        if lst is None:
            return None
        if not isinstance(lst, list):
            return _err("VALIDATION_ERROR", f"{name} must be an array of strings")
        for d in lst:
            if not isinstance(d, str) or len(d.strip()) < 1:
                return _err("VALIDATION_ERROR", f"{name} items must be non-empty strings")
        return None

    e = _validate_domains(include_domains, "include_domains")
    if e:
        api_key_row, _ = _effective_api_key_row(api_key_id)
        _log_call(api_key_row, "tavily-search", "error", (time.time() - t0) * 1000, tokens=0, error={"code": e["error"]["code"]})
        return e
    e = _validate_domains(exclude_domains, "exclude_domains")
    if e:
        api_key_row, _ = _effective_api_key_row(api_key_id)
        _log_call(api_key_row, "tavily-search", "error", (time.time() - t0) * 1000, tokens=0, error={"code": e["error"]["code"]})
        return e

    for bname, bval in (("include_answer", include_answer), ("include_raw_content", include_raw_content), ("include_images", include_images)):
        if bval is None:
            continue
        if not isinstance(bval, bool):
            api_key_row, _ = _effective_api_key_row(api_key_id)
            _log_call(api_key_row, "tavily-search", "error", (time.time() - t0) * 1000, tokens=0, error={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean")

    if raw_input is None:
        raw_input = {}
    if not isinstance(raw_input, dict):
        api_key_row, _ = _effective_api_key_row(api_key_id)
        _log_call(api_key_row, "tavily-search", "error", (time.time() - t0) * 1000, tokens=0, error={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "raw_input must be an object")

    # --- auth + quota ---
    api_key_row, auth_err = _effective_api_key_row(api_key_id)
    if auth_err:
        _log_call(None, "tavily-search", "error", (time.time() - t0) * 1000, tokens=0, error={"code": auth_err["error"]["code"]})
        return auth_err

    quota_err = _enforce_quota(api_key_row)
    if quota_err:
        _log_call(api_key_row, "tavily-search", "error", (time.time() - t0) * 1000, tokens=0, error={"code": quota_err["error"]["code"]})
        return quota_err

    # --- create request row (queued -> running -> succeeded/failed) ---
    search_requests = _load("search_requests.json")
    if not isinstance(search_requests, list):
        search_requests = []

    search_request_id = _ulid_like("srch_req")
    options = {
        "search_depth": search_depth,
        "max_results": max_results,
        "include_domains": include_domains if include_domains is not None else [],
        "exclude_domains": exclude_domains if exclude_domains is not None else [],
        "include_answer": bool(include_answer) if include_answer is not None else False,
        "include_raw_content": bool(include_raw_content) if include_raw_content is not None else False,
        "include_images": bool(include_images) if include_images is not None else False
    }

    req_row = {
        "search_request_id": search_request_id,
        "api_key_id": api_key_row["api_key_id"],
        "status": "queued",
        "raw_input": raw_input if isinstance(raw_input, dict) else {},
        "normalized_query": query,
        "options": options,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    search_requests.append(req_row)
    _save("search_requests.json", search_requests)

    # Transition to running
    req_row["status"] = "running"
    req_row["started_at"] = now_iso
    req_row["updated_at"] = now_iso
    _save("search_requests.json", search_requests)

    # --- deterministic offline "search" results ---
    search_results = _load("search_results.json")
    if not isinstance(search_results, list):
        search_results = []

    def _make_results(q, n):
        # Create stable pseudo-results based on sha256(query|rank)
        out = []
        for r in range(1, n + 1):
            h = hashlib.sha256((q + "|" + str(r)).encode("utf-8")).digest()
            slug = base64.urlsafe_b64encode(h[:9]).decode("ascii").rstrip("=")
            domain = f"example{(h[0] % 9) + 1}.com"
            url = f"https://{domain}/search/{slug}"
            title = f"{q} — Result {r}"
            snippet = f"Offline indexed snippet for '{q}' (rank {r})."
            score = round(1.0 / r, 6)
            out.append({
                "rank": r,
                "url": url,
                "title": title,
                "snippet": snippet,
                "published_at": None,
                "score": score,
                "raw_result": {"offline": True, "query": q, "rank": r, "url": url, "domain": domain}
            })
        return out

    results = _make_results(query, max_results)

    # Apply include/exclude domain filters
    inc = set([d.strip().lower() for d in (include_domains or []) if isinstance(d, str) and d.strip()]) if include_domains is not None else None
    exc = set([d.strip().lower() for d in (exclude_domains or []) if isinstance(d, str) and d.strip()]) if exclude_domains is not None else set()
    filtered = []
    for it in results:
        d = _domain_from_url(it["url"])
        if inc is not None and d not in inc:
            continue
        if d in exc:
            continue
        filtered.append(it)
        if len(filtered) >= max_results:
            break
    results = filtered

    # Persist results rows (unique search_request_id+rank, search_request_id+url)
    created_rows = 0
    for it in results:
        # uniqueness enforcement for this request
        for existing in search_results:
            if existing.get("search_request_id") == search_request_id and (existing.get("rank") == it["rank"] or existing.get("url") == it["url"]):
                continue
        sr_row = {
            "search_result_id": _ulid_like("srch_res"),
            "search_request_id": search_request_id,
            "rank": int(it["rank"]),
            "url": it["url"],
            "title": it.get("title"),
            "snippet": it.get("snippet"),
            "published_at": it.get("published_at"),
            "score": it.get("score"),
            "raw_result": it.get("raw_result") if isinstance(it.get("raw_result"), dict) else {},
            "created_at": now_iso,
            "updated_at": now_iso
        }
        search_results.append(sr_row)
        created_rows += 1

    _save("search_results.json", search_results)

    # Finish request
    req_row["status"] = "succeeded"
    req_row["finished_at"] = now_iso
    req_row["updated_at"] = now_iso
    req_row["error_code"] = None
    req_row["error_message"] = None
    _save("search_requests.json", search_requests)

    # Update api_key last_used_at
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, list):
        for k in api_keys:
            if k.get("api_key_id") == api_key_row["api_key_id"]:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)

    # Increment usage on terminal completion
    usage_all, usage_row = _get_usage(api_key_row["api_key_id"])
    usage_row["completed_requests"] = int(usage_row.get("completed_requests") or 0) + 1
    tokens_used = _token_estimate(query) + sum(_token_estimate((r.get("snippet") or "") + (r.get("title") or "")) for r in [])
    # fix: above sum is wrong if left; compute properly
    tokens_used = _token_estimate(query) + sum(_token_estimate((r.get("title") or "") + " " + (r.get("snippet") or "")) for r in results)
    usage_row["completed_tokens"] = int(usage_row.get("completed_tokens") or 0) + int(tokens_used)
    usage_row["updated_at"] = now_iso
    _save("api_key_usage.json", usage_all)

    # Optional answer
    answer = None
    if options["include_answer"]:
        top_titles = [r.get("title") for r in results[:3] if r.get("title")]
        if top_titles:
            answer = " ".join(top_titles)
        else:
            answer = f"Offline synthesized answer for: {query}"

    latency_ms = (time.time() - t0) * 1000
    _log_call(api_key_row, "tavily-search", "ok", latency_ms, request_id=search_request_id, tokens=int(tokens_used))

    # Response (single page, non-paginated)
    return {
        "search_request": req_row,
        "results": results,
        "answer": answer,
        "meta": {
            "max_results": max_results,
            "returned_results": len(results),
            "stored_results": created_rows
        }
    }

def tavily_extract(api_key_id=None, urls=None, include_raw_content=None, extract_text=None, raw_input=None, **_extra):
    import json, os, datetime, time, re, secrets
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0242000" if __import__("os").path.isdir("./environment_mix/0242000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")
    day_key = now.strftime("%Y-%m-%d")

    CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(prefix):
        rand = "".join(secrets.choice(CROCKFORD) for _ in range(16))
        return f"{prefix}_{rand}"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _token_estimate(text):
        if not text:
            return 0
        return max(1, len(text) // 4)

    def _log_call(api_key_row, endpoint, status, latency_ms, request_id=None, tokens=0, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rec = {
            "request_log_id": _ulid_like("reqlog"),
            "endpoint": endpoint,
            "api_key_id": api_key_row["api_key_id"] if api_key_row else None,
            "api_key_prefix": api_key_row.get("key_prefix") if api_key_row else None,
            "request_id": request_id,
            "status": status,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "timestamp": now_iso,
            "latency_ms": int(latency_ms),
            "utc_day": day_key,
            "tokens": int(tokens) if isinstance(tokens, int) else 0
        }
        logs.append(rec)
        _save("request_logs.json", logs)

    def _get_usage(api_key_id):
        usage = _load("api_key_usage.json")
        if not isinstance(usage, list):
            usage = []
        row = None
        for r in usage:
            if r.get("api_key_id") == api_key_id and r.get("utc_day") == day_key:
                row = r
                break
        if row is None:
            row = {"api_key_id": api_key_id, "utc_day": day_key, "completed_requests": 0, "completed_tokens": 0, "updated_at": now_iso}
            usage.append(row)
            _save("api_key_usage.json", usage)
        return usage, row

    def _count_completed_from_store(api_key_id):
        sr = _load("search_requests.json")
        er = _load("extract_requests.json")
        if not isinstance(sr, list): sr = []
        if not isinstance(er, list): er = []
        terminals = {"succeeded", "failed", "cancelled"}
        c = 0
        for r in sr:
            if r.get("api_key_id") == api_key_id and r.get("status") in terminals:
                dt = _parse_dt(r.get("finished_at")) or _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at"))
                if dt and dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%d") == day_key:
                    c += 1
        for r in er:
            if r.get("api_key_id") == api_key_id and r.get("status") in terminals:
                dt = _parse_dt(r.get("finished_at")) or _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at"))
                if dt and dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%d") == day_key:
                    c += 1
        return c

    def _effective_api_key_row(api_key_id_param):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        if api_key_id_param is not None:
            if not isinstance(api_key_id_param, str):
                return None, _err("VALIDATION_ERROR", "api_key_id must be a string")
            if not re.match(r"^tav_key_[0-9A-HJKMNP-TV-Z]{10,}$", api_key_id_param):
                return None, _err("VALIDATION_ERROR", "api_key_id has invalid format")
            for k in keys:
                if k.get("api_key_id") == api_key_id_param:
                    return k, None
            return None, _err("UNAUTHORIZED", "API key not found")
        for k in keys:
            if k.get("status") == "active":
                return k, None
        return None, _err("UNAUTHORIZED", "No active API key available")

    def _enforce_quota(api_key_row):
        if api_key_row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active")
        q = api_key_row.get("quota_daily_requests")
        if not isinstance(q, int) or q < 0:
            return _err("UNAUTHORIZED", "API key quota is invalid")
        usage_all, usage_row = _get_usage(api_key_row["api_key_id"])
        completed = usage_row.get("completed_requests")
        if not isinstance(completed, int) or completed < 0:
            completed = 0
        completed_store = _count_completed_from_store(api_key_row["api_key_id"])
        if completed_store > completed:
            usage_row["completed_requests"] = completed_store
            usage_row["updated_at"] = now_iso
            _save("api_key_usage.json", usage_all)
            completed = completed_store
        if completed >= q:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota_daily_requests=q, completed_requests=completed, utc_day=day_key)
        return None

    def _valid_abs_url(u):
        if not isinstance(u, str) or not u:
            return False
        try:
            p = urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    # --- validate inputs ---
    if urls is None or not isinstance(urls, list) or len(urls) < 1:
        api_key_row, _ = _effective_api_key_row(api_key_id)
        _log_call(api_key_row, "tavily-extract", "error", (time.time() - t0) * 1000, tokens=0, error={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "urls must be a non-empty array")

    for u in urls:
        if not _valid_abs_url(u):
            api_key_row, _ = _effective_api_key_row(api_key_id)
            _log_call(api_key_row, "tavily-extract", "error", (time.time() - t0) * 1000, tokens=0, error={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Each url must be a valid absolute http(s) URI")

    if include_raw_content is None:
        include_raw_content = False
    if extract_text is None:
        extract_text = True

    if not isinstance(include_raw_content, bool):
        api_key_row, _ = _effective_api_key_row(api_key_id)
        _log_call(api_key_row, "tavily-extract", "error", (time.time() - t0) * 1000, tokens=0, error={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_raw_content must be a boolean")
    if not isinstance(extract_text, bool):
        api_key_row, _ = _effective_api_key_row(api_key_id)
        _log_call(api_key_row, "tavily-extract", "error", (time.time() - t0) * 1000, tokens=0, error={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "extract_text must be a boolean")

    if raw_input is None:
        raw_input = {}
    if not isinstance(raw_input, dict):
        api_key_row, _ = _effective_api_key_row(api_key_id)
        _log_call(api_key_row, "tavily-extract", "error", (time.time() - t0) * 1000, tokens=0, error={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "raw_input must be an object")

    # --- auth + quota ---
    api_key_row, auth_err = _effective_api_key_row(api_key_id)
    if auth_err:
        _log_call(None, "tavily-extract", "error", (time.time() - t0) * 1000, tokens=0, error={"code": auth_err["error"]["code"]})
        return auth_err

    quota_err = _enforce_quota(api_key_row)
    if quota_err:
        _log_call(api_key_row, "tavily-extract", "error", (time.time() - t0) * 1000, tokens=0, error={"code": quota_err["error"]["code"]})
        return quota_err

    # --- create request row ---
    extract_requests = _load("extract_requests.json")
    if not isinstance(extract_requests, list):
        extract_requests = []
    extract_request_id = _ulid_like("extr_req")

    options = {
        "include_raw_content": include_raw_content,
        "extract_text": extract_text,
        "fetch_timeout_ms": 10000,
        "max_bytes": 2000000,
        "extraction_mode": "readability"
    }

    req_row = {
        "extract_request_id": extract_request_id,
        "api_key_id": api_key_row["api_key_id"],
        "status": "queued",
        "raw_input": raw_input if isinstance(raw_input, dict) else {},
        "options": options,
        "requested_url_count": int(len(urls)),
        "succeeded_url_count": 0,
        "failed_url_count": 0,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    extract_requests.append(req_row)
    _save("extract_requests.json", extract_requests)

    # running
    req_row["status"] = "running"
    req_row["started_at"] = now_iso
    req_row["updated_at"] = now_iso
    _save("extract_requests.json", extract_requests)

    extracted_documents = _load("extracted_documents.json")
    if not isinstance(extracted_documents, list):
        extracted_documents = []

    # Create one row per URL (unique per request+url)
    docs_out = []
    succeeded = 0
    failed = 0
    tokens_used = 0

    for u in urls:
        # Dedup within request list: process each unique URL once; mark duplicates as skipped
        # but still must create row per URL? schema says unique(extract_request_id,url), so duplicates cannot have multiple rows.
        # We'll treat duplicates as single row and return one document for that URL.
        if any(d.get("extract_request_id") == extract_request_id and d.get("url") == u for d in extracted_documents):
            continue

        doc_id = _ulid_like("extr_doc")
        p = urlparse(u)
        host = (p.hostname or "").lower()
        # offline "fetch": fail for obviously bad hosts
        is_fail = host == "" or host.endswith(".invalid")

        if is_fail:
            status = "failed"
            http_status = None
            content_type = None
            raw_content = None
            extracted_text_val = None
            meta = {}
            err_code = "FETCH_FAILED"
            err_msg = "Could not fetch URL"
            failed += 1
        else:
            status = "succeeded"
            http_status = 200
            content_type = "text/html; charset=utf-8"
            raw_html = f"<html><head><title>{u}</title></head><body><p>Offline fetched content for {u}</p></body></html>"
            raw_content = raw_html if include_raw_content else None
            extracted_text_val = f"Offline extracted text for {u}" if extract_text else None
            meta = {"title": u, "source": "offline", "host": host}
            err_code = None
            err_msg = None
            succeeded += 1

        fetch_ms = 5
        proc_ms = 3

        row = {
            "extracted_document_id": doc_id,
            "extract_request_id": extract_request_id,
            "url": u,
            "final_url": u,
            "status": status,
            "http_status": http_status,
            "content_type": content_type,
            "raw_content": raw_content,
            "extracted_text": extracted_text_val,
            "extracted_metadata": meta if isinstance(meta, dict) else {},
            "fetch_duration_ms": fetch_ms,
            "process_duration_ms": proc_ms,
            "error_code": err_code,
            "error_message": err_msg,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        extracted_documents.append(row)
        docs_out.append(row)

        tokens_used += _token_estimate(u)
        if extracted_text_val:
            tokens_used += _token_estimate(extracted_text_val)

    _save("extracted_documents.json", extracted_documents)

    # finish request (succeeded if any succeeded OR if all failed? we'll mark failed only when all failed)
    req_row["succeeded_url_count"] = int(succeeded)
    req_row["failed_url_count"] = int(failed)
    req_row["finished_at"] = now_iso
    req_row["updated_at"] = now_iso

    if succeeded == 0 and failed > 0:
        req_row["status"] = "failed"
        req_row["error_code"] = "ALL_URLS_FAILED"
        req_row["error_message"] = "All URLs failed extraction"
    else:
        req_row["status"] = "succeeded"
        req_row["error_code"] = None
        req_row["error_message"] = None

    _save("extract_requests.json", extract_requests)

    # Update api_key last_used_at
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, list):
        for k in api_keys:
            if k.get("api_key_id") == api_key_row["api_key_id"]:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)

    # Increment usage on terminal completion
    usage_all, usage_row = _get_usage(api_key_row["api_key_id"])
    usage_row["completed_requests"] = int(usage_row.get("completed_requests") or 0) + 1
    usage_row["completed_tokens"] = int(usage_row.get("completed_tokens") or 0) + int(tokens_used)
    usage_row["updated_at"] = now_iso
    _save("api_key_usage.json", usage_all)

    latency_ms = (time.time() - t0) * 1000
    _log_call(api_key_row, "tavily-extract", "ok", latency_ms, request_id=extract_request_id, tokens=int(tokens_used))

    return {
        "extract_request": req_row,
        "documents": docs_out,
        "meta": {
            "requested_url_count": req_row["requested_url_count"],
            "succeeded_url_count": req_row["succeeded_url_count"],
            "failed_url_count": req_row["failed_url_count"]
        }
    }

def tavily_search_requests_list(api_key_id, status=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, re, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0242000" if __import__("os").path.isdir("./environment_mix/0242000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")
    day_key = now.strftime("%Y-%m-%d")

    CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(prefix):
        rand = "".join(secrets.choice(CROCKFORD) for _ in range(16))
        return f"{prefix}_{rand}"

    def _log_call(api_key_row, endpoint, status_s, latency_ms, tokens=0, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rec = {
            "request_log_id": _ulid_like("reqlog"),
            "endpoint": endpoint,
            "api_key_id": api_key_row["api_key_id"] if api_key_row else None,
            "api_key_prefix": api_key_row.get("key_prefix") if api_key_row else None,
            "request_id": None,
            "status": status_s,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "timestamp": now_iso,
            "latency_ms": int(latency_ms),
            "utc_day": day_key,
            "tokens": int(tokens) if isinstance(tokens, int) else 0
        }
        logs.append(rec)
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    # validate api_key_id
    if not isinstance(api_key_id, str) or not re.match(r"^tav_key_[0-9A-HJKMNP-TV-Z]{10,}$", api_key_id):
        _log_call(None, "tavily-search-requests.list", "error", (time.time() - t0) * 1000, error={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "api_key_id has invalid format")

    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "running", "succeeded", "failed", "cancelled"):
            _log_call(None, "tavily-search-requests.list", "error", (time.time() - t0) * 1000, error={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled")

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log_call(None, "tavily-search-requests.list", "error", (time.time() - t0) * 1000, error={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "page_size must be an integer in range 1–200")

    ca = _parse_dt(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        _log_call(None, "tavily-search-requests.list", "error", (time.time() - t0) * 1000, error={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 date-time string")
    cb = _parse_dt(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        _log_call(None, "tavily-search-requests.list", "error", (time.time() - t0) * 1000, error={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 date-time string")

    # auth: api key must exist and be active
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    key_row = None
    for k in api_keys:
        if k.get("api_key_id") == api_key_id:
            key_row = k
            break
    if key_row is None:
        _log_call(None, "tavily-search-requests.list", "error", (time.time() - t0) * 1000, error={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "API key not found")
    if key_row.get("status") != "active":
        _log_call(key_row, "tavily-search-requests.list", "error", (time.time() - t0) * 1000, error={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "API key is not active")

    # decode page token
    cursor_created_at = None
    cursor_id = None
    if page_token is not None:
        if not isinstance(page_token, str) or len(page_token) < 1:
            _log_call(key_row, "tavily-search-requests.list", "error", (time.time() - t0) * 1000, error={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "page_token must be a non-empty string")
        try:
            payload = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===").decode("utf-8")
            parts = payload.split("|", 1)
            if len(parts) != 2:
                raise ValueError("bad token")
            cursor_created_at = _parse_dt(parts[0])
            cursor_id = parts[1]
        except Exception:
            _log_call(key_row, "tavily-search-requests.list", "error", (time.time() - t0) * 1000, error={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid page_token")

        if cursor_created_at is None or not cursor_id:
            _log_call(key_row, "tavily-search-requests.list", "error", (time.time() - t0) * 1000, error={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid page_token")

    # load and filter
    reqs = _load("search_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    def _req_created_dt(r):
        return _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    filtered = []
    for r in reqs:
        if r.get("api_key_id") != api_key_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        rdt = _req_created_dt(r)
        if ca is not None and not (rdt > ca):
            continue
        if cb is not None and not (rdt <= cb):
            continue
        filtered.append(r)

    # sort created_at desc, tie-breaker search_request_id desc
    filtered.sort(key=lambda r: (_req_created_dt(r), str(r.get("search_request_id") or "")), reverse=True)

    # apply cursor: items strictly after cursor in this ordering are earlier in list; we return next page after cursor,
    # so skip until we pass the cursor item.
    if cursor_created_at is not None and cursor_id is not None:
        new_list = []
        passed = False
        for r in filtered:
            rdt = _req_created_dt(r)
            rid = str(r.get("search_request_id") or "")
            if not passed:
                if rdt == cursor_created_at and rid == cursor_id:
                    passed = True
                continue
            new_list.append(r)
        filtered = new_list

    total = len(filtered)
    page = filtered[:page_size]
    has_more = len(filtered) > page_size

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = _req_created_dt(last).isoformat().replace("+00:00", "Z")
        last_id = str(last.get("search_request_id") or "")
        token_raw = f"{last_dt}|{last_id}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token_raw).decode("utf-8").rstrip("=")

    latency_ms = (time.time() - t0) * 1000
    _log_call(key_row, "tavily-search-requests.list", "ok", latency_ms)

    return {
        "data": page,
        "meta": {
            "page_size": page_size,
            "total_matched": total,
            "has_more": bool(has_more),
            "next_page_token": next_cursor
        }
    }

def tavily_search_results_list(api_key_id, search_request_id, page_size=None, page_token=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0242000" if __import__("os").path.isdir("./environment_mix/0242000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "tavily-search-results.list"

    def _utcnow_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log_call(api_key_used, status_s, error=None, request_id=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "event_id": f"evt_{int(time.time()*1000)}_{os.getpid()}_{int((time.time()%1)*1e9)}",
            "endpoint": endpoint,
            "api_key_id": api_key_used,
            "request_id": request_id,
            "status": status_s,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "timestamp": _utcnow_iso(),
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)

    def _decode_token(tok):
        # token encodes an integer offset
        try:
            raw = base64.urlsafe_b64decode(tok.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("off:"):
                return None
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_token(off):
        b = f"off:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    # Validate
    if not isinstance(api_key_id, str):
        e = _err("VALIDATION_ERROR", "api_key_id must be a string.")
        _log_call(api_key_id if isinstance(api_key_id, str) else None, "error", e["error"])
        return e
    if not re.match(r"^tav_key_[0-9A-HJKMNP-TV-Z]{10,}$", api_key_id):
        e = _err("VALIDATION_ERROR", "api_key_id format is invalid.")
        _log_call(api_key_id, "error", e["error"])
        return e

    if not isinstance(search_request_id, str) or not search_request_id.strip():
        e = _err("VALIDATION_ERROR", "search_request_id must be a non-empty string.")
        _log_call(api_key_id, "error", e["error"])
        return e
    if not (re.match(r"^srch_req_[0-9A-HJKMNP-TV-Z]{10,}$", search_request_id) or re.match(r"^tav_srch_[0-9A-HJKMNP-TV-Z]{10,}$", search_request_id)):
        e = _err("VALIDATION_ERROR", "search_request_id format is invalid (expected srch_req_... or tav_srch_...).")
        _log_call(api_key_id, "error", e["error"], request_id=search_request_id)
        return e

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int):
        e = _err("VALIDATION_ERROR", "page_size must be an integer.")
        _log_call(api_key_id, "error", e["error"], request_id=search_request_id)
        return e
    if page_size < 1 or page_size > 200:
        e = _err("VALIDATION_ERROR", "page_size must be between 1 and 200.")
        _log_call(api_key_id, "error", e["error"], request_id=search_request_id)
        return e

    offset = 0
    if page_token is not None:
        if not isinstance(page_token, str) or not page_token:
            e = _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided.")
            _log_call(api_key_id, "error", e["error"], request_id=search_request_id)
            return e
        off = _decode_token(page_token)
        if off is None:
            e = _err("VALIDATION_ERROR", "page_token is invalid.")
            _log_call(api_key_id, "error", e["error"], request_id=search_request_id)
            return e
        offset = off

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    key_row = next((k for k in api_keys if k.get("api_key_id") == api_key_id), None)
    if not key_row:
        e = _err("UNAUTHORIZED", "API key not found.")
        _log_call(api_key_id, "error", e["error"], request_id=search_request_id)
        return e
    if key_row.get("status") != "active":
        e = _err("UNAUTHORIZED", "API key is not active.")
        _log_call(api_key_id, "error", e["error"], request_id=search_request_id)
        return e

    search_requests = _load("search_requests.json")
    if not isinstance(search_requests, list):
        search_requests = []
    parent = next((r for r in search_requests if r.get("search_request_id") == search_request_id), None)
    if not parent:
        e = _err("NOT_FOUND", "Search request not found.")
        _log_call(api_key_id, "error", e["error"], request_id=search_request_id)
        return e
    if parent.get("api_key_id") != api_key_id:
        e = _err("UNAUTHORIZED", "Search request does not belong to the provided API key.")
        _log_call(api_key_id, "error", e["error"], request_id=search_request_id)
        return e

    search_results = _load("search_results.json")
    if not isinstance(search_results, list):
        search_results = []

    rows = [r for r in search_results if r.get("search_request_id") == search_request_id]
    # order by rank ascending (rank may be missing/corrupt => send to end deterministically)
    def _rank_key(r):
        rk = r.get("rank")
        return (0, rk) if isinstance(rk, int) else (1, 10**18)
    rows.sort(key=_rank_key)

    total = len(rows)
    page = rows[offset:offset + page_size]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_token(next_off) if has_more else None

    _log_call(api_key_id, "ok", request_id=search_request_id)
    return {
        "results": page,
        "page": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_cursor
        }
    }

def tavily_extract_requests_list(api_key_id, status=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0242000" if __import__("os").path.isdir("./environment_mix/0242000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "tavily-extract-requests.list"
    api_keys = _load("api_keys.json")
    extract_requests = _load("extract_requests.json")

    def _utcnow_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field_name):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 date-time string.")
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 date-time string.")

    def _log_call(status_s, api_key_used, error=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "event_id": f"evt_{int(time.time()*1000)}_{os.getpid()}_{int((time.time()%1)*1e9)}",
            "endpoint": endpoint,
            "api_key_id": api_key_used,
            "status": status_s,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "timestamp": _utcnow_iso(),
            "latency_ms": latency_ms,
        }
        reqlog = _load("request_logs.json")
        if not isinstance(reqlog, list):
            reqlog = []
        reqlog.append(row)
        _save("request_logs.json", reqlog)

    # Validate
    if not isinstance(api_key_id, str):
        e = _err("VALIDATION_ERROR", "api_key_id must be a string.")
        _log_call("error", api_key_id if isinstance(api_key_id, str) else None, e["error"])
        return e
    if not re.match(r"^tav_key_[0-9A-HJKMNP-TV-Z]{10,}$", api_key_id):
        e = _err("VALIDATION_ERROR", "api_key_id format is invalid.")
        _log_call("error", api_key_id, e["error"])
        return e

    if status is not None:
        if not isinstance(status, str):
            e = _err("VALIDATION_ERROR", "status must be a string.")
            _log_call("error", api_key_id, e["error"])
            return e
        if status not in {"queued", "running", "succeeded", "failed", "cancelled"}:
            e = _err("VALIDATION_ERROR", "status is invalid.")
            _log_call("error", api_key_id, e["error"])
            return e

    ca_dt, err = _parse_dt(created_after, "created_after")
    if err:
        _log_call("error", api_key_id, err["error"])
        return err
    cb_dt, err = _parse_dt(created_before, "created_before")
    if err:
        _log_call("error", api_key_id, err["error"])
        return err

    if page_size is None:
        ps = 50
    else:
        if not isinstance(page_size, int):
            e = _err("VALIDATION_ERROR", "page_size must be an integer.")
            _log_call("error", api_key_id, e["error"])
            return e
        if page_size < 1 or page_size > 200:
            e = _err("VALIDATION_ERROR", "page_size must be between 1 and 200.")
            _log_call("error", api_key_id, e["error"])
            return e
        ps = page_size

    if page_token is not None and (not isinstance(page_token, str) or len(page_token) < 1):
        e = _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided.")
        _log_call("error", api_key_id, e["error"])
        return e

    key = next((k for k in api_keys if k.get("api_key_id") == api_key_id), None)
    if not key:
        e = _err("NOT_FOUND", "API key not found.")
        _log_call("error", api_key_id, e["error"])
        return e

    # Refuse access when the API key is not active.
    if key.get("status") != "active":
        e = _err("UNAUTHORIZED", "API key is not active.")
        _log_call("error", api_key_id, e["error"])
        return e

    # Pagination token: base64url JSON: {"offset": int}
    offset = 0
    if page_token is not None:
        try:
            padded = page_token + "=" * (-len(page_token) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            tok = json.loads(raw)
            if not isinstance(tok, dict) or not isinstance(tok.get("offset"), int) or tok["offset"] < 0:
                e = _err("VALIDATION_ERROR", "page_token is invalid.")
                _log_call("error", api_key_id, e["error"])
                return e
            offset = tok["offset"]
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            e = _err("VALIDATION_ERROR", "page_token is invalid.")
            _log_call("error", api_key_id, e["error"])
            return e

    # Filter
    def _row_dt(row):
        s = row.get("created_at")
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    rows = [r for r in extract_requests if r.get("api_key_id") == api_key_id]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if ca_dt is not None:
        rows = [r for r in rows if (_row_dt(r) is not None and _row_dt(r) > ca_dt)]
    if cb_dt is not None:
        rows = [r for r in rows if (_row_dt(r) is not None and _row_dt(r) <= cb_dt)]

    # Order by created_at desc (fallback to id)
    rows.sort(key=lambda r: (_row_dt(r) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), r.get("extract_request_id") or ""), reverse=True)

    total = len(rows)
    page = rows[offset:offset + ps]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    _log_call("ok", api_key_id, None)
    return {
        "object": "list",
        "data": page,
        "page_size": ps,
        "next_page_token": next_cursor,
        "has_more": has_more,
        "total": total,
    }

def tavily_extracted_documents_list(api_key_id, extract_request_id, status=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0242000" if __import__("os").path.isdir("./environment_mix/0242000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "tavily-extracted-documents.list"

    def _utcnow_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_call(api_key_used, status_s, error=None, request_id=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "event_id": f"evt_{int(time.time()*1000)}_{os.getpid()}_{int((time.time()%1)*1e9)}",
            "endpoint": endpoint,
            "api_key_id": api_key_used,
            "request_id": request_id,
            "status": status_s,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "timestamp": _utcnow_iso(),
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)

    def _decode_token(tok):
        try:
            raw = base64.urlsafe_b64decode(tok.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("off:"):
                return None
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_token(off):
        b = f"off:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    # Validate
    if not isinstance(api_key_id, str):
        e = _err("VALIDATION_ERROR", "api_key_id must be a string.")
        _log_call(api_key_id if isinstance(api_key_id, str) else None, "error", e["error"])
        return e
    if not re.match(r"^tav_key_[0-9A-HJKMNP-TV-Z]{10,}$", api_key_id):
        e = _err("VALIDATION_ERROR", "api_key_id format is invalid.")
        _log_call(api_key_id, "error", e["error"])
        return e

    if not isinstance(extract_request_id, str) or not extract_request_id.strip():
        e = _err("VALIDATION_ERROR", "extract_request_id must be a non-empty string.")
        _log_call(api_key_id, "error", e["error"])
        return e
    # Accept both the tool-advertised prefix (ext_req_) and the datastore prefix (tav_ext_)
    if not (re.match(r"^ext_req_[0-9A-HJKMNP-TV-Z]{10,}$", extract_request_id) or re.match(r"^tav_ext_[0-9A-HJKMNP-TV-Z]{10,}$", extract_request_id)):
        e = _err("VALIDATION_ERROR", "extract_request_id format is invalid (expected ext_req_... or tav_ext_...).")
        _log_call(api_key_id, "error", e["error"], request_id=extract_request_id)
        return e

    allowed_status = {"queued", "fetching", "processing", "succeeded", "failed", "skipped"}
    if status is not None:
        if not isinstance(status, str):
            e = _err("VALIDATION_ERROR", "status must be a string when provided.")
            _log_call(api_key_id, "error", e["error"], request_id=extract_request_id)
            return e
        if status not in allowed_status:
            e = _err("VALIDATION_ERROR", "status must be one of: queued, fetching, processing, succeeded, failed, skipped.")
            _log_call(api_key_id, "error", e["error"], request_id=extract_request_id)
            return e

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int):
        e = _err("VALIDATION_ERROR", "page_size must be an integer.")
        _log_call(api_key_id, "error", e["error"], request_id=extract_request_id)
        return e
    if page_size < 1 or page_size > 200:
        e = _err("VALIDATION_ERROR", "page_size must be between 1 and 200.")
        _log_call(api_key_id, "error", e["error"], request_id=extract_request_id)
        return e

    offset = 0
    if page_token is not None:
        if not isinstance(page_token, str) or not page_token:
            e = _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided.")
            _log_call(api_key_id, "error", e["error"], request_id=extract_request_id)
            return e
        off = _decode_token(page_token)
        if off is None:
            e = _err("VALIDATION_ERROR", "page_token is invalid.")
            _log_call(api_key_id, "error", e["error"], request_id=extract_request_id)
            return e
        offset = off

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    key_row = next((k for k in api_keys if k.get("api_key_id") == api_key_id), None)
    if not key_row:
        e = _err("UNAUTHORIZED", "API key not found.")
        _log_call(api_key_id, "error", e["error"], request_id=extract_request_id)
        return e
    if key_row.get("status") != "active":
        e = _err("UNAUTHORIZED", "API key is not active.")
        _log_call(api_key_id, "error", e["error"], request_id=extract_request_id)
        return e

    extract_requests = _load("extract_requests.json")
    if not isinstance(extract_requests, list):
        extract_requests = []
    parent = next((r for r in extract_requests if r.get("extract_request_id") == extract_request_id), None)
    if not parent:
        e = _err("NOT_FOUND", "Extract request not found.")
        _log_call(api_key_id, "error", e["error"], request_id=extract_request_id)
        return e
    if parent.get("api_key_id") != api_key_id:
        e = _err("UNAUTHORIZED", "Extract request does not belong to the provided API key.")
        _log_call(api_key_id, "error", e["error"], request_id=extract_request_id)
        return e

    extracted_documents = _load("extracted_documents.json")
    if not isinstance(extracted_documents, list):
        extracted_documents = []

    rows = [d for d in extracted_documents if d.get("extract_request_id") == extract_request_id]
    if status is not None:
        rows = [d for d in rows if d.get("status") == status]

    # ordered by created_at ascending (fallback to updated_at, then id)
    def _sort_key(d):
        ca = _parse_dt(d.get("created_at"))
        ua = _parse_dt(d.get("updated_at"))
        return (
            ca if ca is not None else (ua if ua is not None else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)),
            str(d.get("extracted_document_id") or "")
        )
    rows.sort(key=_sort_key)

    total = len(rows)
    page = rows[offset:offset + page_size]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_token(next_off) if has_more else None

    _log_call(api_key_id, "ok", request_id=extract_request_id)
    return {
        "documents": page,
        "page": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_cursor
        }
    }

def tavily_auth_whoami(api_key_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0242000" if __import__("os").path.isdir("./environment_mix/0242000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "tavily-auth.whoami"
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    extract_requests = _load("extract_requests.json")

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _utcnow_iso():
        return _utcnow().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_call(status_s, api_key_used, error=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "event_id": f"evt_{int(time.time()*1000)}_{os.getpid()}_{int((time.time()%1)*1e9)}",
            "endpoint": endpoint,
            "api_key_id": api_key_used,
            "status": status_s,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "timestamp": _utcnow_iso(),
            "latency_ms": latency_ms,
        }
        reqlog = _load("request_logs.json")
        if not isinstance(reqlog, list):
            reqlog = []
        reqlog.append(row)
        _save("request_logs.json", reqlog)

    # Validate
    if not isinstance(api_key_id, str):
        e = _err("VALIDATION_ERROR", "api_key_id must be a string.")
        _log_call("error", api_key_id if isinstance(api_key_id, str) else None, e["error"])
        return e
    if not re.match(r"^tav_key_[0-9A-HJKMNP-TV-Z]{10,}$", api_key_id):
        e = _err("VALIDATION_ERROR", "api_key_id format is invalid.")
        _log_call("error", api_key_id, e["error"])
        return e

    key = next((k for k in api_keys if k.get("api_key_id") == api_key_id), None)
    if not key:
        e = _err("NOT_FOUND", "API key not found.")
        _log_call("error", api_key_id, e["error"])
        return e

    # Usage: count completed requests created today UTC, across search + extract.
    completed = {"succeeded", "failed", "cancelled"}
    today = _utcnow().date()

    used_requests = 0
    for r in search_requests:
        if r.get("api_key_id") == api_key_id and r.get("status") in completed:
            ca = _parse_dt(r.get("created_at"))
            if ca and ca.astimezone(datetime.timezone.utc).date() == today:
                used_requests += 1
    for r in extract_requests:
        if r.get("api_key_id") == api_key_id and r.get("status") in completed:
            ca = _parse_dt(r.get("created_at"))
            if ca and ca.astimezone(datetime.timezone.utc).date() == today:
                used_requests += 1

    quota_req = key.get("quota_daily_requests")
    if not isinstance(quota_req, int) or quota_req < 0:
        quota_req = 0

    # Tokens quota is schema'd but no token accounting exists in store; expose 0 used.
    quota_tok = key.get("quota_daily_tokens")
    if not isinstance(quota_tok, int) or quota_tok < 0:
        quota_tok = 0

    resp = {
        "object": "identity",
        "api_key": {
            "api_key_id": key.get("api_key_id"),
            "key_prefix": key.get("key_prefix"),
            "label": key.get("label"),
            "status": key.get("status"),
            "created_at": key.get("created_at"),
            "updated_at": key.get("updated_at"),
            "last_used_at": key.get("last_used_at"),
        },
        "entitlements": {
            "scopes": ["search:read", "extract:read", "whoami:read"],
        },
        "usage_utc_day": {
            "date": today.isoformat(),
            "requests_used": used_requests,
            "requests_quota": quota_req,
            "tokens_used": 0,
            "tokens_quota": quota_tok,
            "requests_remaining": max(0, quota_req - used_requests),
            "tokens_remaining": max(0, quota_tok - 0),
        },
    }

    _log_call("ok", api_key_id, None)
    return resp
